'use client';
import { useRef, useState, type CSSProperties, type FormEvent } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { enter, Fold, Swap, Tip, useGrow } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import { usePopover } from '../lib/popover';
import '../designme.css';
// its menus' rows glide in Clean
import '../lib/glide';
import './knowledge-sources.css';

/** files: uploaded files, web: a website the agent crawls, folder: a connected folder of docs (Notion, Drive and the like) */
export type KnowledgeSourceKind = 'files' | 'web' | 'folder';

/** queued: waiting its turn, indexing: being read (with a progress bar), ready: indexed, failed: stopped, with a reason */
export type KnowledgeSourceState = 'queued' | 'indexing' | 'ready' | 'failed';

/** A file, site or folder the agent knows */
export interface KnowledgeSource {
  key: string;
  /** Like "Product docs" or "designme.dev/docs" */
  name: string;
  kind: KnowledgeSourceKind;
  /** How many pages or files it holds, like 142 */
  count: number;
  /** Defaults to pages */
  unit?: 'pages' | 'files';
  state: KnowledgeSourceState;
  /** While indexing: how many of `count` are done. The bar and "64 of 142 pages" follow it */
  done?: number;
  /** When ready: when it was last synced, like "2m ago", shown as "Synced 2m ago" */
  synced?: string;
  /** When failed: why, like "Scanned PDF, no text found" */
  error?: string;
  /** When failed: the label of a button that fixes it, like "Retry with OCR". It calls `onFix` */
  fix?: string;
  /** Replaces "Queued" while it waits, like "Queued to read with OCR" */
  note?: string;
  /** The chunks it adds to the index, counted in the line under the title. Leave it out until it has been indexed */
  chunks?: number;
}

/** A folder offered under Connect a folder */
export interface KnowledgeSourcesFolder {
  key: string;
  name: string;
  /** Where it lives, like "Google Drive" */
  detail?: string;
}

export interface KnowledgeSourcesProps {
  sources: KnowledgeSource[];
  /** Adds Upload files to the Add source menu; it opens the file picker and hands you what was picked */
  onUpload?: (files: File[]) => void;
  /** Adds Add a website to the Add source menu; it asks for an address and hands it over without http(s):// */
  onAddWebsite?: (address: string) => void;
  /** The address being typed. Leave it out to let the field keep its own */
  address?: string;
  defaultAddress?: string;
  onAddressChange?: (address: string) => void;
  /** Adds Connect a folder to the Add source menu, listing these */
  folders?: KnowledgeSourcesFolder[];
  onConnectFolder?: (key: string) => void;
  /** Adds Re-sync to each source's menu. It is unavailable while the source waits or indexes */
  onResync?: (key: string) => void;
  /** Adds Remove to each source's menu, and beside the fix of a failed one */
  onRemove?: (key: string) => void;
  /** Called by the fix button of a failed source */
  onFix?: (key: string) => void;
  /** Defaults to "Knowledge sources" */
  title?: string;
  /** The line under the title. Defaults to how many chunks are indexed, like "1,204 chunks indexed" */
  status?: string;
  className?: string;
}

/* a type's icon on a vivid tile of its colour, with the colour's own ink */
const KIND: Record<KnowledgeSourceKind, [IconName, string]> = { files: ['file-text', 'p'], web: ['globe', 'b'], folder: ['folder', 'm'] };
const fmt = (n: number) => n.toLocaleString('en-US');
const of = (n: number, unit: string) => `${fmt(n)} ${n === 1 ? unit.slice(0, -1) : unit}`;
const line = (s: KnowledgeSource) => s.state === 'queued' ? s.note ?? 'Queued' : s.state === 'failed' ? s.error ?? 'Failed'
  : of(s.count, s.unit ?? 'pages') + (s.synced ? ' · Synced ' + s.synced : '');
/* the line's mark: a tick once indexed, a clock while it waits, a sign when it failed */
const MARK: Record<Exclude<KnowledgeSourceState, 'indexing'>, IconName> = { ready: 'ok', queued: 'clock', failed: 'alert' };

/** One source: its type, name and state, and a menu with Re-sync and Remove */
function Row({ s, delay, onResync, onRemove, onFix }: { s: KnowledgeSource; delay: number } & Pick<KnowledgeSourcesProps, 'onResync' | 'onRemove' | 'onFix'>) {
  const menu = usePopover({ align: 'end' });
  const [icon, k] = KIND[s.kind];
  const motion = enter(delay), unit = s.unit ?? 'pages', done = Math.min(s.count, Math.max(0, Math.floor(s.done ?? 0)));
  const busy = s.state === 'queued' || s.state === 'indexing';
  const act = (f?: (key: string) => void) => { menu.closeSoon(); f?.(s.key); };
  return (
    <div className={cx('dm-ksx-s', motion.className)} style={motion.style} role="listitem" data-st={s.state}>
      <span className="dm-ic" style={{ background: `var(--dm-av-${k})`, color: `var(--dm-av-${k}-ink)` }} aria-hidden="true"><Icon name={icon} size="xs" /></span>
      <span className="dm-t">
        <span className="dm-nm">{s.name}</span>
        <span className="dm-d">
          {s.state === 'indexing'
            ? <><span className="dm-ksx-bar" role="progressbar" aria-label={'Indexing ' + s.name} aria-valuemin={0} aria-valuemax={s.count} aria-valuenow={done}><i style={{ width: done / (s.count || 1) * 100 + '%' }} /></span><span className="dm-num dm-shim">{fmt(done)} of {of(s.count, unit)}</span></>
            : <><Icon name={MARK[s.state]} size="xs" /><Swap>{line(s)}</Swap></>}
        </span>
      </span>
      {(onResync || onRemove)
        ? <Tip label="More" off={menu.open}><button type="button" className="dm-ib dm-ksx-more dm-mx-press" aria-label={'Actions for ' + s.name} {...menu.trigger}><Icon name="more" /></button></Tip>
        : <span />}
      {(onResync || onRemove) && (
        <div {...menu.pop} className={cx(menu.pop.className, 'dm-ksx-mpop dm-mx-pop dm-mx-rows dm-mx-glide')} role="menu">
          {onResync && <button type="button" className="dm-mi dm-mx-press" role="menuitem" disabled={busy} onClick={() => act(onResync)}><Icon name="refresh" size="xs" />Re-sync</button>}
          {onResync && onRemove && <div className="dm-sep" />}
          {onRemove && <button type="button" className="dm-mi dm-del dm-mx-press" role="menuitem" onClick={() => act(onRemove)}><Icon name="trash" size="xs" />Remove</button>}
        </div>
      )}
      <Fold open={s.state === 'failed' && !!(s.fix || onRemove)} className="dm-ksx-fx">
        <div>
          {s.fix && <button type="button" className="dm-pill dm-accent dm-sm" onClick={() => onFix?.(s.key)}>{s.fix}</button>}
          {onRemove && <button type="button" className="dm-pill dm-ghost dm-sm dm-mx-press" onClick={() => onRemove(s.key)}>Remove</button>}
        </div>
      </Fold>
    </div>
  );
}

/** What the agent knows: files, websites and connected folders, each with how far it is indexed. One that failed says why
    and can offer a fix; Add source uploads files, adds a website or connects a folder. */
export function KnowledgeSources({ sources, onUpload, onAddWebsite, address, defaultAddress = '', onAddressChange, folders = [], onConnectFolder,
  onResync, onRemove, onFix, title = 'Knowledge sources', status, className }: KnowledgeSourcesProps) {
  const file = useRef<HTMLInputElement>(null);
  // Clean's one hover: a highlight that glides from source to source
  const listRef = useRef<HTMLDivElement>(null);
  useHoverGlide(listRef, '.dm-ksx-s');
  const field = useRef<HTMLInputElement>(null);
  // a menu opens under its button, or above it when there is no room
  const menu = usePopover();
  // the card grows with its rows and shrinks as they go, eased (as grow() on the site)
  const [root, inner] = useGrow();
  const [view, setView] = useState<'main' | 'web' | 'folder'>('main');
  const [url, setUrl] = useControllable(address, defaultAddress, onAddressChange);
  // a menu that opened above Add source grows upwards whichever step it shows, so it is held by its bottom edge
  const [bottom, setBottom] = useState<CSSProperties>({});
  const up = String((menu.pop.style as Record<string, unknown>)['--dm-origin'] ?? '').startsWith('bottom');
  useIsoLayoutEffect(() => {
    const b = root.current?.querySelector<HTMLElement>('.dm-ksx-add,.dm-ksx-em .dm-pill'), r = b?.getBoundingClientRect(), h = root.current?.getBoundingClientRect();
    setBottom(menu.open && up && r && h ? { top: 'auto', bottom: h.bottom - r.top + 6 } : {});
  }, [menu.open, view, up]);
  // rows there from the start come in one after another; a row added later comes in on its own
  const [first] = useState(() => sources.map(s => s.key));
  const total = status ?? `${fmt(sources.reduce((a, s) => a + (s.chunks ?? 0), 0))} chunks indexed`;
  const canAdd = !!(onUpload || onAddWebsite || onConnectFolder);
  const submit = (e: FormEvent) => {
    e.preventDefault();
    const v = url.trim().replace(/^https?:\/\//, '').replace(/\/$/, '');
    if (!v) { field.current?.focus(); return; }
    menu.close(); setUrl(''); onAddWebsite?.(v);
  };
  return (
    <div data-dm="" ref={root} className={cx('dm-ksx dm-panel dm-growing dm-mx-grow', className)}>
      <div ref={inner} className="dm-grow">
      <div className="dm-ksx-h"><span className="dm-ksx-hi" aria-hidden="true"><Icon name="book" size="xs" /></span><div><b>{title}</b><Swap className="dm-muted dm-ksx-st">{total}</Swap></div></div>
      <div ref={listRef} className="dm-ksx-list dm-mx-glide" role="list" aria-label="Sources">
        {sources.map(s => { const at = first.indexOf(s.key); return <Row key={s.key} s={s} delay={at >= 0 ? at * 50 : 0} onResync={onResync} onRemove={onRemove} onFix={onFix} />; })}
      </div>
      {/* nothing left: the empty state, with Add source as an outline button */}
      {!sources.length && (
        <div className="dm-ksx-em"><span className="dm-ksx-em-art" aria-hidden="true" /><b>No sources yet</b><span>Add files, a website or a folder, and the agent reads them.</span>
          {canAdd && <button type="button" className="dm-pill dm-line dm-sm dm-mx-press" {...menu.trigger} onClick={e => { if (!menu.open) setView('main'); menu.trigger.onClick(e); }}><Icon name="plus" size="xs" />Add source</button>}
        </div>
      )}
      {canAdd && <>
        {sources.length > 0 && <div className="dm-ksx-ft"><button type="button" className="dm-ksx-add dm-mx-press" {...menu.trigger} onClick={e => { if (!menu.open) setView('main'); menu.trigger.onClick(e); }}><Icon name="plus" size="xs" />Add source</button></div>}
        <div {...menu.pop} style={{ ...menu.pop.style, ...bottom }} className={cx(menu.pop.className, 'dm-ksx-pop dm-mx-pop dm-mx-rows dm-mx-glide')} role="menu" aria-label="Add source">
          {view === 'main' && <>
            {onUpload && <button type="button" className="dm-mi dm-mx-press" role="menuitem" onClick={() => { menu.closeSoon(); file.current?.click(); }}><Icon name="upload" size="xs" /><span>Upload files</span></button>}
            {onAddWebsite && <button type="button" className="dm-mi dm-mx-press" role="menuitem" onClick={() => { setView('web'); requestAnimationFrame(() => field.current?.focus({ preventScroll: true })); }}><Icon name="globe" size="xs" /><span>Add a website</span></button>}
            {onConnectFolder && <button type="button" className="dm-mi dm-mx-press" role="menuitem" onClick={() => setView('folder')}><Icon name="folder" size="xs" /><span>Connect a folder</span></button>}
          </>}
          {view === 'web' && (
            <form className="dm-ksx-web" onSubmit={submit}>
              <div className="dm-ph">Add a website</div>
              <div className="dm-ksx-in"><Icon name="globe" size="xs" /><input ref={field} value={url} onChange={e => setUrl(e.target.value)} placeholder="example.com/docs" aria-label="Website address" spellCheck={false} autoComplete="off" /><button type="submit" className="dm-pill dm-accent dm-sm">Add</button></div>
            </form>
          )}
          {view === 'folder' && <>
            <div className="dm-ph">Connect a folder</div>
            {folders.length
              ? folders.map(f => <button type="button" key={f.key} className="dm-mi dm-mx-press" role="menuitem" onClick={() => { menu.closeSoon(); onConnectFolder?.(f.key); }}><Icon name="folder" size="xs" /><span>{f.name}{f.detail && <span className="dm-d">{f.detail}</span>}</span></button>)
              : <div className="dm-ph">All folders connected</div>}
          </>}
        </div>
        {onUpload && <input ref={file} type="file" multiple hidden title="" onChange={e => { const fs = [...(e.target.files ?? [])]; e.target.value = ''; if (fs.length) onUpload(fs); }} />}
      </>}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Knowledge sources ---------- */
/* what the agent knows: each source with its type, its size and how far it is indexed. The card sits on two columns (owner,
   18 Nov), its content 16px from every edge: the head's neutral mark in a 28px column with each source's mark under it, and
   the title and each source's words 12px after it; the menu buttons' glyphs end on the content's right edge. A row is not a
   button, so it has no hover fill. The line under a source's name is its state, led by its mark (beside it, never over the
   source's own): a green tick and what it holds once it is indexed, a clock while it waits, a bar and a count that shimmers
   while it is read, and a red sign with the reason once it has failed, with a fix under it. A type's mark is a vivid tile of
   its colour with white or the colour's own ink on it. The card grows and shrinks with its rows (grow()) */
.dm-ksx{padding:var(--dm-s-4);display:flex;flex-direction:column}
.dm-ksx.dm-growing:has(.dm-pop.dm-open){overflow:visible}
.dm-ksx-h{display:flex;align-items:center;gap:var(--dm-s-3);padding-bottom:var(--dm-s-2)}
.dm-ksx-hi{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));color:var(--dm-fg2);background:var(--dm-chip)}
.dm-ksx-h>div{flex:1;display:flex;flex-direction:column;min-width:0}
.dm-ksx-h b{font-weight:500;font-size:14px;line-height:20px}
.dm-ksx-st{font-size:12px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-ksx-list{display:flex;flex-direction:column}
.dm-ksx-s{display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);padding:var(--dm-s-2) 0;font-size:13px}
.dm-ksx-s .dm-ic{width:28px;height:28px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center}
.dm-ksx-s .dm-t{min-width:0;display:flex;flex-direction:column}
.dm-ksx-s .dm-nm{line-height:20px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-ksx-s .dm-d{display:flex;align-items:center;gap:5px;min-width:0;height:18px;font-size:12px;color:var(--dm-muted)}
.dm-ksx-s .dm-d>span:last-child{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-ksx-s .dm-d>.dm-i{flex:none;color:var(--dm-muted)}
.dm-ksx-s[data-st="ready"] .dm-d>.dm-i{color:var(--dm-ok-mark)}
.dm-ksx-s[data-st="failed"] .dm-d{color:var(--dm-bad)}
/* why it failed is never cut short: on a narrow card it wraps, its sign on the first line */
.dm-ksx-s[data-st="failed"] .dm-d{height:auto;min-height:18px;align-items:flex-start;line-height:18px}
.dm-ksx-s[data-st="failed"] .dm-d>.dm-i{margin-top:3px}
.dm-ksx-s[data-st="failed"] .dm-d>span:last-child{white-space:normal;text-wrap:pretty}
.dm-ksx-s[data-st="failed"] .dm-d>.dm-i{color:var(--dm-bad-mark)}
.dm-ksx-s .dm-d .dm-shim{font-size:inherit}
.dm-ksx-s[data-st="indexing"] .dm-d{gap:var(--dm-s-2)}
.dm-ksx-bar{width:56px;height:4px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-line);overflow:hidden;flex:none}
.dm-ksx-bar i{display:block;height:100%;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transition:width .2s linear}
/* the menu button: its hover circle ends on the content's right edge (a box that fills keeps the card's 16px) */
.dm-ksx-more{width:28px;height:28px}
.dm-ksx-s .dm-ksx-fx{grid-column:2/-1}
.dm-ksx-fx>div{overflow-clip-margin:0px}
.dm-ksx-fx>div>div{display:flex;flex-wrap:wrap;gap:6px;padding-top:var(--dm-s-2)}
/* Add source: its + centred in the marks' column and its words on the title's; the hover box starts on the content's edge */
.dm-ksx-add{display:flex;align-items:center;gap:var(--dm-s-3);align-self:flex-start;height:32px;margin-top:var(--dm-s-1);padding:0 var(--dm-s-3) 0 0;font-size:13px;color:var(--dm-fg2);border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
.dm-ksx-add>.dm-i{width:28px;padding:0 8px;box-sizing:border-box}
.dm-ksx-add[aria-expanded="true"]{color:var(--dm-fg);background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-ksx-add:hover{color:var(--dm-fg);background:var(--dm-row)}}
.dm-ksx-pop{width:248px}
/* its motion (the core's motion pieces, owner, 26 Nov): its menus grow out of their buttons and go back quicker, their rows
   settle one after another (a menu's next step too) and one highlight glides between them; one highlight glides from source to
   source in every style (.mx-glide); a press shows at once (.mx-press); the card grows on the spring (.mx-grow) */
.dm-ksx-mpop{min-width:160px}
.dm-ksx-mpop .dm-mi.dm-del,.dm-ksx-mpop .dm-mi.dm-del .dm-i{color:var(--dm-bad)}
@media (hover:hover) and (pointer:fine){.dm-ksx-mpop .dm-mi.dm-del:hover{background:var(--dm-bad-bg)}}
.dm-ksx-mpop .dm-mi[disabled],.dm-ksx-mpop .dm-mi[disabled] .dm-i{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis)}
.dm-ksx-web{display:flex;flex-direction:column;gap:var(--dm-s-1)}
/* (the field holds the site's small button, 28px, with 4px round it) */
.dm-ksx-in{display:flex;align-items:center;gap:var(--dm-s-2);height:36px;margin:0 2px 2px;padding:0 var(--dm-s-1) 0 10px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);color:var(--dm-muted);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-ksx-in{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dm-ksx-in:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-ksx-in input{flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--dm-fg)}
.dm-ksx-in input::placeholder{color:var(--dm-muted)}
/* nothing left: the empty state (the lab's, lab/clean): a small sketch of the list on a white card, a title, one muted line
   and Add source as an outline button */
.dm-ksx-em{display:flex;flex-direction:column;align-items:center;gap:4px;padding:16px 16px 20px;text-align:center}
.dm-ksx-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.dm-ksx-em>span:not(.dm-ksx-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.dm-ksx-em .dm-pill{margin-top:12px}
.dm-ksx-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 16px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.dm-ksx-em-art::before{content:"";position:absolute;left:14px;top:13px;width:12px;height:12px;border-radius:4px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-wash))}
.dm-ksx-em-art::after{content:"";position:absolute;left:34px;top:16px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-wash))}
.dm-ksx-list:not(:empty)~.dm-ksx-em,.dm-ksx-list:empty~.dm-ksx-ft{display:none}
/* the foot sits under a hairline in Soft and Blueprint (owner, 21 Nov), its button's words 16px from the hairline and 16px from
   the card's bottom edge (owner, 23 Nov): the ghost button's 32px box reaches 6px round its words, so the foot has 10px above it
   and reaches 6px into the card's bottom padding. Clean's is a foot strip */
.dm-ksx-ft{margin-bottom:-6px;padding-top:10px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-ksx-ft .dm-ksx-add{margin-top:0}
.dm-shx-ft{margin-bottom:-6px;padding-top:10px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-shx-ft .dm-shx-add{margin-top:0}
:root:not([data-style="soft"],[data-style="clean"]) .dm-ksx-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-rail) 60%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) :is(.dm-ksx-em-art::before,.dm-ksx-em-art::after):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){border-radius:0}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.dm-ksx :is(.dm-ib,.dm-pill):active,:root[data-style="clean"] .dm-ksx .dm-ib:active,:root [data-style="clean"] .dm-ksx .dm-ib:active,:root [data-style="clean"].dm-ksx .dm-ib:active{transform:none}
/* Clean (owner, 17 and 18 Nov): the head an off-white strip with a hairline under it; the sources' marks one neutral grey
   with a hairline; Add source a flat secondary button on an off-white foot strip, 16px from the card's edges and the
   strip's hairline (owner, 23 Nov); the content 16px
   in from each edge and 16px from each strip; menus scale and fade from their button, with the card's corners */
:root[data-style="clean"] .dm-ksx.dm-panel,:root [data-style="clean"] .dm-ksx.dm-panel,:root [data-style="clean"].dm-ksx.dm-panel{padding:0}
